'use strict';
// Read-only adapter for the existing small-phone music manifest and export formats.
// Only the prototype's queue changes. Never writes to yibeiMusic or the phone save.
window.RoseDollMusic=(()=>{
  let tracks=[],current=-1,media=null,ownedURL='',playToken=0,onUpdate=()=>{},error='',source='';
  const emit=()=>onUpdate();
  function safeSong(row,i){if(!row||typeof row!=='object')return null;const id=typeof row.id==='string'?row.id:'import-'+i;return{id,title:String(row.title||'未命名歌曲').slice(0,180),artist:String(row.artist||'').slice(0,100),src:row.src&&typeof row.src==='object'?{t:row.src.t,url:row.src.url}:null,mediaKind:row.mediaKind==='video'?'video':'audio',file:typeof row.file==='string'?row.file:'',blob:row.blob instanceof Blob?row.blob:null,fileSize:Number(row.fileSize)||0};}
  async function readOnlyGet(key){if(!window.indexedDB)return null;if(indexedDB.databases){const dbs=await indexedDB.databases();if(!dbs.some(d=>d.name==='yibeiMusic'))return null;}return new Promise(resolve=>{let done=false,db=null;const finish=value=>{if(done)return;done=true;clearTimeout(timer);db?.close();resolve(value);};const timer=setTimeout(()=>finish(null),3000);const r=indexedDB.open('yibeiMusic');r.onupgradeneeded=()=>{r.transaction.abort();finish(null);};r.onerror=()=>finish(null);r.onblocked=()=>finish(null);r.onsuccess=()=>{db=r.result;if(done){db.close();return;}if(!db.objectStoreNames.contains('audio')){finish(null);return;}const tx=db.transaction('audio','readonly');let value=null;const q=tx.objectStore('audio').get(key);q.onsuccess=()=>{value=q.result;};tx.oncomplete=()=>finish(value);tx.onerror=()=>finish(null);tx.onabort=()=>finish(null);};});}
  function stop(){playToken++;if(media){media.pause();media.removeAttribute('src');media.load();media.remove();media=null;}if(ownedURL){URL.revokeObjectURL(ownedURL);ownedURL='';}emit();}
  async function refresh(){error='';try{const row=await readOnlyGet('__music_manifest_v1');if(row?.music&&Array.isArray(row.music.songs)&&row.music.songs.length){const nextTracks=row.music.songs.slice(0,1000).map(safeSong).filter(Boolean);if(JSON.stringify(nextTracks)!==JSON.stringify(tracks)){stop();tracks=nextTracks;current=-1;}source='原音乐软件 · 我的歌单';}else if(!tracks.length){source='';}}catch{error='暂时无法读取本机歌单。';}emit();return tracks.length;}
  async function importPack(file){error='';if(!file)return;try{const magic='NORTHMUSIC2\n',prefix=new Uint8Array(await file.slice(0,magic.length+4).arrayBuffer());let rows;
      if(new TextDecoder().decode(prefix.slice(0,magic.length))===magic){const n=new DataView(prefix.buffer).getUint32(magic.length,true);if(!n||n>2*1024*1024||magic.length+4+n>=file.size)throw Error('单曲包头部不完整');const at=magic.length+4+n,header=JSON.parse(await file.slice(magic.length+4,at).text());if(header.type!=='yibei-music-binary'||header.ver!==2||!header.music?.song)throw Error('不是小手机音乐单曲包');if(header.audio?.size&&header.audio.size!==file.size-at)throw Error('单曲包音频不完整');rows=[{...header.music.song,blob:file.slice(at,file.size,header.audio?.type||'audio/mpeg')}];
      }else{if(file.size>24*1024*1024)throw Error('歌单文件较大，请在原音乐软件使用分首导出');const pack=JSON.parse(await file.text());if(pack.type!=='yibei-music-pack'||pack.ver!==1||!Array.isArray(pack.music?.songs))throw Error('请选择原音乐软件导出的歌单 JSON 或单曲包');rows=pack.music.songs;}
      const result=rows.slice(0,1000).map(safeSong).filter(Boolean);if(!result.length)throw Error('这份歌单没有歌曲');stop();tracks=result;current=-1;source='原音乐软件导出 · '+file.name;error='';
    }catch(e){error=e.message||'歌单读取失败';}emit();}
  async function resolveURL(song){if(song.blob)return{url:URL.createObjectURL(song.blob),owned:true};if(song.file){if(!/^data:(audio\/[^;,]+|video\/[^;,]+|application\/octet-stream);base64,[A-Za-z0-9+/=]+$/.test(song.file))throw Error('这首歌曲的音频数据无法识别');const blob=await(await fetch(song.file)).blob();return{url:URL.createObjectURL(blob),owned:true};}if(song.src?.t==='url'){const url=new URL(String(song.src.url));if(!['https:','http:'].includes(url.protocol))throw Error('歌曲地址协议不支持');return{url:url.href,owned:false};}const blob=await readOnlyGet(song.id);if(!(blob instanceof Blob)||!blob.size||(song.fileSize&&song.fileSize!==blob.size))throw Error('这首歌的本地音频不在当前试玩地址，请从原音乐软件导出后选择');return{url:URL.createObjectURL(blob),owned:true};}
  async function play(index){if(!tracks[index])return;document.dispatchEvent(new Event("rose-doll:library-play"));stop();const token=++playToken;current=index;error='';emit();let result;try{result=await resolveURL(tracks[index]);if(token!==playToken){if(result.owned)URL.revokeObjectURL(result.url);return;}ownedURL=result.owned?result.url:'';const el=document.createElement(tracks[index].mediaKind==='video'?'video':'audio');media=el;el.dataset.libraryAudio='true';el.preload='metadata';el.volume=.45;el.setAttribute('playsinline','');el.setAttribute('webkit-playsinline','');el.style.cssText='position:fixed;width:1px;height:1px;left:-10px;top:-10px;pointer-events:none;opacity:0';document.body.append(el);el.onplay=emit;el.onpause=emit;el.onended=()=>{if(token===playToken&&tracks.length)play((index+1)%tracks.length);};el.onerror=()=>{if(token===playToken){error='这首歌暂时无法播放，请换一首或检查原音频。';emit();}};el.src=result.url;await el.play();if(token===playToken)emit();}catch(e){if(token===playToken){error=e.name==='NotAllowedError'?'请再点一次播放，浏览器需要你的点按授权。':e.message||'播放失败';emit();}}}
  async function toggle(){if(!media){await play(current<0?0:current);return;}if(media.paused){try{await media.play();error='';}catch{error='请重新点选这首歌。';}}else media.pause();emit();}
  function next(){if(tracks.length)play((Math.max(current,0)+1)%tracks.length);}
  function previous(){if(tracks.length)play((Math.max(current,0)-1+tracks.length)%tracks.length);}
  function mount(root){onUpdate=()=>{if(root.isConnected)render(root);};render(root);refresh();}
  function render(root){root.replaceChildren();const defaults=document.createElement('div');root.append(defaults);window.RoseDollSound?.mount(defaults);const info=document.createElement('p');info.className='panel-copy';info.textContent=tracks.length?source+' · '+tracks.length+' 首':'此独立试玩地址还没有原音乐歌单。可选择原音乐软件导出的歌单或单曲包；不会修改原歌单。';root.append(info);const actions=document.createElement('div');actions.className='music-actions';const choose=document.createElement('label');choose.className='music-import';choose.textContent='选择原音乐歌单';const input=document.createElement('input');input.type='file';input.accept='.json,.bin,.music,.northmusic,application/json,application/x-smallphone-music';input.hidden=true;input.onchange=()=>importPack(input.files[0]);choose.append(input);const reload=document.createElement('button');reload.textContent='重新读取';reload.onclick=refresh;actions.append(choose,reload);root.append(actions);if(error){const p=document.createElement('p');p.className='music-error';p.textContent=error;root.append(p);}if(tracks.length){const controls=document.createElement('div');controls.className='music-controls';for(const[text,fn]of [['上一首',previous],[media&&!media.paused?'暂停':'播放',toggle],['下一首',next]]){const b=document.createElement('button');b.textContent=text;b.onclick=fn;controls.append(b);}root.append(controls);}const list=document.createElement('div');list.className='music-list';tracks.forEach((song,i)=>{const b=document.createElement('button');b.className='music-track'+(i===current?' current':'');const title=document.createElement('b');title.textContent=song.title;const small=document.createElement('small');small.textContent=song.artist||'本机音乐';const playing=document.createElement('em');playing.textContent=i===current?(media&&!media.paused?'播放中':'已选择'):String(i+1).padStart(2,'0');b.append(playing,title,small);b.onclick=()=>play(i);list.append(b);});root.append(list);}
  window.addEventListener('pagehide',stop);
  return{mount,refresh,importPack,stop};
})();
